sqlite3 experiments.sqlite "SELECT id, metrics_json FROM experiments ORDER BY id DESC LIMIT 15;" | python3 -c "
import sys, json
for line in sys.stdin:
    line=line.rstrip('\n')
    if not line: continue
    i, js = line.split('|',1)
    try: m=json.loads(js)
    except Exception as e: print(i, 'bad json', e); continue
    print('=== exp', i)
    for k in ['mission_score','usable_fix_rate','false_fix_rate','abstain_rate','coverage','median_error_m','p10_error_m','model_bytes','latency_ms']:
        if k in m: print('  ',k, m[k])
    tcd = m.get('train_capture_diagnostics')
    if tcd:
        print('   train_capture_diagnostics:')
        if isinstance(tcd, dict):
            for cap, v in tcd.items():
                if isinstance(v, dict):
                    print('     ', cap, {kk: v[kk] for kk in v if kk in ('mission_score','usable_fix_rate','false_fix_rate','abstain_rate','median_error_m','coverage')})
                else: print('     ', cap, v)
        else: print('     ', tcd)
    for k in ['per_bucket','buckets','eval','region_holdout','region_holdout_diagnostics']:
        if k in m: print('  ',k, json.dumps(m[k])[:800])
    print('   keys:', list(m.keys()))
"
